mapper.select:
/* SQL ID : DscsAtclDAO.count 설명 : 게시글 목록 수 조회 */ SELECT COUNT(*) FROM TB_LMS_DSCS_ATCL A LEFT JOIN TB_LMS_USER U ON U.USER_ID = A.RGTR_ID WHERE A.DSCS_ID = #{dscsId}
AND (A.DELYN IN ('N', 'H') OR EXISTS ( SELECT 1 FROM TB_LMS_DSCS_CMNT C WHERE C.DSCS_ATCL_ID = A.DSCS_ATCL_ID AND C.DELYN = 'N' ))
AND ( LOWER(U.STDNT_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(U.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
AND A.USER_ID IN
#{item}

/* SQL ID : DscsAtclDAO.listPageing 설명 : 게시글 페이징 목록 조회 */
SELECT ROW_NUMBER() OVER (ORDER BY A.ATCL_SEQNO ASC, A.REG_DTTM DESC) AS LINE_NO , A.DSCS_ATCL_ID , A.DSCS_ID , A.UP_DSCS_ATCL_ID , NVL(A.ATCL_LV, 0) AS ATCL_LV , NVL(A.ATCL_SEQNO, 0) AS ATCL_SEQNO , A.DSCS_ATCL_TYCD , A.OKNOK_GBNCD , A.ATCL_TTL , A.ATCL_CTS , A.ATCL_CTS_LEN , NVL(A.INQ_CNT, 0) AS INQ_CNT , U.USERNM , U.STDNT_NO , A.RGTR_ID , A.REG_DTTM , A.MDFR_ID , A.MOD_DTTM , A.EDTR_USEYN , A.DELYN , A.USER_ID , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT C WHERE C.DSCS_ATCL_ID = A.DSCS_ATCL_ID AND C.DELYN = 'N') AS cmntCount , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT C WHERE C.DSCS_ATCL_ID = A.DSCS_ATCL_ID AND C.DELYN = 'N' AND C.USER_ID = A.USER_ID) AS writerCmntCount , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT C WHERE C.DSCS_ATCL_ID = A.DSCS_ATCL_ID AND C.DELYN = 'N' AND C.USER_ID = #{userId}) AS viewerCmntCount , (SELECT MAX(B.ATCL_SEQNO) FROM TB_LMS_DSCS_ATCL B WHERE B.DSCS_ID = A.DSCS_ID AND B.DELYN = 'N') AS maxOdr , '' AS phtFileByte FROM TB_LMS_DSCS_ATCL A LEFT JOIN TB_LMS_USER U ON U.USER_ID = A.RGTR_ID WHERE A.DSCS_ID = #{dscsId}
AND (A.DELYN IN ('N', 'H') OR EXISTS ( SELECT 1 FROM TB_LMS_DSCS_CMNT C WHERE C.DSCS_ATCL_ID = A.DSCS_ATCL_ID AND C.DELYN = 'N' ))
AND ( LOWER(U.STDNT_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(U.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
AND A.USER_ID IN
#{item}
ORDER BY A.ATCL_SEQNO ASC, A.REG_DTTM DESC

mapper.insert:
/*
    SQL ID : DscsAtclDAO.insertAtcl
    설명 : 게시글 등록
*/
INSERT INTO TB_LMS_DSCS_ATCL (
      DSCS_ATCL_ID
    , DSCS_ID
    , USER_ID
    , UP_DSCS_ATCL_ID
    , ATCL_LV
    , ATCL_SEQNO
    , DSCS_ATCL_TYCD
    , OKNOK_GBNCD
    , ATCL_TTL
    , ATCL_CTS
    , ATCL_CTS_LEN
    , INQ_CNT
    , EDTR_USEYN
    , DELYN
    , RGTR_ID
    , REG_DTTM
    , MDFR_ID
    , MOD_DTTM
) VALUES (
      #{dscsAtclId}
    , #{dscsId}
    , #{userId}
    , #{upDscsAtclId}
    , 0
    , #{atclSeqno}
    , #{dscsAtclTycd}
    , #{oknokGbncd}
    , #{atclTtl}
    , #{atclCts}
    , #{atclCtsLen}
    , 0
    , 'N'
    , 'N'
    , #{userId}
    , FN_DTTM()
    , #{userId}
    , FN_DTTM()
)

mapper.update:
/*
    SQL ID : DscsAtclDAO.updateAtcl
    설명 : 게시글 수정
*/
UPDATE TB_LMS_DSCS_ATCL
SET MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()

  , UP_DSCS_ATCL_ID = #{upDscsAtclId}


  , ATCL_LV = #{atclLv}


  , ATCL_SEQNO = #{atclSeqno}


  , DSCS_ATCL_TYCD = #{dscsAtclTycd}


  , OKNOK_GBNCD = #{oknokGbncd}


  , ATCL_TTL = #{atclTtl}


  , ATCL_CTS = #{atclCts}
  , ATCL_CTS_LEN = #{atclCtsLen}


  , INQ_CNT = #{inqCnt}


  , EDTR_USEYN = #{edtrUseyn}


  , DELYN = #{delyn}

WHERE DSCS_ATCL_ID = #{dscsAtclId}
  AND DSCS_ID = #{dscsId}

/*
    SQL ID : DscsAtclDAO.deleteAtcl
    설명 : 게시글 삭제 처리
*/
UPDATE TB_LMS_DSCS_ATCL
SET DELYN = 'Y'
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE DSCS_ATCL_ID = #{dscsAtclId}
  AND DSCS_ID = #{dscsId}

/*
    SQL ID : DscsAtclDAO.hideAtcl
    설명 : 게시글 숨김 처리
*/
UPDATE TB_LMS_DSCS_ATCL
SET DELYN = 'H'
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE DSCS_ATCL_ID = #{dscsAtclId}
  AND DSCS_ID = #{dscsId}

mapper.select:
/*
    SQL ID : DscsAtclDAO.selectMyAtclStatus
    설명 : 본인 게시글 작성 상태 조회
*/
SELECT
      COUNT(1) AS DSCS_ATCL_CNT
    , MIN(A.OKNOK_GBNCD) KEEP (DENSE_RANK FIRST ORDER BY A.ATCL_SEQNO ASC, A.REG_DTTM DESC) AS OKNOK_GBNCD
FROM TB_LMS_DSCS_ATCL A
WHERE A.DSCS_ID = #{dscsId}
  AND A.USER_ID = #{userId}
  AND A.DELYN = 'N'
  AND EXISTS (
        SELECT 1
        FROM TB_LMS_ATNDLC B
        WHERE B.SBJCT_ID = #{sbjctId}
          AND B.USER_ID = A.USER_ID
          AND B.USER_ID = #{userId}
          AND B.ATNDLC_STSCD = 'APPROVE'
  )

/* SQL ID : DscsAtclDAO.listEzgActivityAtcl 설명 : EZ-Grader 토론 활동 게시글 목록 조회 */ SELECT A.DSCS_ATCL_ID , A.DSCS_ID , A.UP_DSCS_ATCL_ID , NVL(A.ATCL_LV, 0) AS ATCL_LV , NVL(A.ATCL_SEQNO, 0) AS ATCL_SEQNO , A.DSCS_ATCL_TYCD , A.OKNOK_GBNCD , A.ATCL_TTL , A.ATCL_CTS , A.ATCL_CTS_LEN , NVL(A.INQ_CNT, 0) AS INQ_CNT , U.USERNM , U.STDNT_NO , A.RGTR_ID , A.REG_DTTM , A.MDFR_ID , A.MOD_DTTM , A.EDTR_USEYN , A.DELYN , A.USER_ID , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT C WHERE C.DSCS_ATCL_ID = A.DSCS_ATCL_ID) AS cmntCount , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT C WHERE C.DSCS_ATCL_ID = A.DSCS_ATCL_ID AND C.USER_ID = A.USER_ID) AS writerCmntCount FROM TB_LMS_DSCS_ATCL A LEFT JOIN TB_LMS_USER U ON U.USER_ID = A.RGTR_ID WHERE A.DSCS_ID = #{dscsId} AND ( A.USER_ID IN
#{item}
OR EXISTS ( SELECT 1 FROM TB_LMS_DSCS_CMNT C WHERE C.DSCS_ATCL_ID = A.DSCS_ATCL_ID AND C.USER_ID IN
#{item}
) ) ORDER BY A.USER_ID ASC, A.ATCL_SEQNO ASC, A.REG_DTTM DESC
